SELECT payload,payload::text FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('raw',to_jsonb(d),'relation',to_jsonb(pg_identify_object('pg_class'::regclass,d.adrelid,0)),'column',to_jsonb(pg_identify_object('pg_class'::regclass,d.adrelid,d.adnum)),'expression',pg_get_expr(d.adbin,d.adrelid,false)) ORDER BY d.oid),'[]'::jsonb) AS payload FROM pg_attrdef d WHERE d.adrelid IN (SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace UNION SELECT reltoastrelid FROM pg_class WHERE relnamespace='public'::regnamespace AND reltoastrelid<>0 UNION SELECT i.indexrelid FROM pg_index i JOIN pg_class c ON c.reltoastrelid=i.indrelid WHERE c.relnamespace='public'::regnamespace)) AS capture